import{_ as d,o as e,c as o,ag as a}from"./chunks/framework.BoXUJ6sC.js";const f=JSON.parse('{"title":"부록. 팀 합의 후 반영한 것","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/appendix.md","filePath":"kafka/appendix.md"}'),r={name:"kafka/appendix.md"};function c(n,t,s,i,l,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="부록-팀-합의-후-반영한-것" tabindex="-1">부록. 팀 합의 후 반영한 것 <a class="header-anchor" href="#부록-팀-합의-후-반영한-것" aria-label="Permalink to &quot;부록. 팀 합의 후 반영한 것&quot;">​</a></h1><table tabindex="0"><thead><tr><th>항목</th><th>반영 내용</th></tr></thead><tbody><tr><td>토픽</td><td>보내는 도메인마다 하나(<code>kidly.{보내는도메인}.events</code>)입니다. 재고 이벤트는 <code>kidly.product.events</code>, 구매확정은 <code>kidly.order.events</code>, 자녀 변경은 <code>kidly.childprofile.events</code>에 들어갑니다</td></tr><tr><td>읽기 실패</td><td>모르는 enum 값처럼 읽지 못한 메시지는 재시도 없이 DLT로 보내고 Slack으로 알립니다</td></tr><tr><td>읽기 시작 위치</td><td><code>auto-offset-reset: latest</code>입니다. 첫 배포 때 오프셋을 맞추는 명령을 쓰지 않습니다</td></tr><tr><td><code>max.block.ms</code></td><td>앱은 기본값(60초)입니다. 문제가 생기면 그때 바꿉니다</td></tr><tr><td>오프셋 보존 기간</td><td>기본값(7일)입니다</td></tr><tr><td>재시도 · 트랜잭션</td><td>재시도 정책과 리스너의 <code>@Transactional</code>은 각 도메인이 정합니다</td></tr><tr><td>테스트</td><td>Kafka 컨테이너는 <code>@KafkaIntegrationTest</code>에서만 띄우고, 나머지 테스트는 보내기 스위치로 Kafka 보내기를 끕니다. 결과는 <code>support.AsyncWait</code>로 기다립니다</td></tr><tr><td>ArchUnit</td><td>모든 받는 쪽을 옮긴 뒤 마무리 단계에 넣습니다</td></tr><tr><td>DLT 목적지</td><td>DLT 전송기의 기본 목적지(<code>{토픽}-dlt</code>)를 쓰지 않고 <code>{토픽}.{받는도메인}.dlt</code>, 파티션 <code>-1</code>로 지정합니다</td></tr><tr><td>전송 실패 로그</td><td>앱은 Boot 기본 템플릿의 실패를 토픽 · 키 · <code>eventType</code> · <code>eventId</code>로 남기고 본문은 빼며, 직접 만든 템플릿은 기본 실패 로그를 끄고 실패를 직접 남깁니다</td></tr></tbody></table>',2)])])}const k=d(r,[["render",c]]);export{f as __pageData,k as default};
